using A33.Instrument.Protocol;
static class Program { static void Main(){ var req=ModbusRequestCodec.ReadHolding(1,0,2); if(!req.SequenceEqual(new byte[]{1,3,0,0,0,2})) throw new Exception("FC03"); if(ModbusCrc16.Compute(new byte[]{1,3,0,0,0,2})!=0x0bc4) throw new Exception("CRC"); var tcp=ModbusTcpCodec.Encode(1,1,req.AsSpan(1)); if(!tcp.SequenceEqual(Convert.FromHexString("000100000006010300000002"))) throw new Exception("TCP"); if(RegisterValueCodec.Int64(new ushort[]{0xffff,0xffff,0xffff,0xffff})!=-1) throw new Exception("int64"); Console.WriteLine("Protocol tests passed"); } }
